(function(E){ const x = E["mkt-m3"] = E["mkt-m3"] || {units:{}}; x.units["mkt-12"] = {"grammar":{"id":"c-mkt-12-g","level":"B1","course":"marketing","unit":"mkt-12","title":"Plans with conditions: if + present, will; unless","titleTr":"Koşullu planlar: if + geniş zaman, will; unless","titleFa":"برنامه با شرط: if + حال ساده، will؛ unless","formsTable":{"headers":{"en":["Condition","Result"],"tr":["Koşul","Sonuç"],"fa":["شرط","نتیجه"]},"rows":[["If the towels sell well,","the retailer will order for more stores."],["If repeat orders keep growing,","we will reach 150 orders a week."],["Unless the certificates arrive on time,","the bathrobes will be late."]]},"wrong":"If the test will go well, the retailer will order more.","right":"If the test goes well, the retailer will order more.","blank":{"sentence":"If the test ___ well, the retailer will roll the towels out in the autumn.","word":"goes","distractors":["will go","went"]},"wrong2":"Unless the certificates don't arrive, the bathrobes will be late.","right2":"Unless the certificates arrive, the bathrobes will be late.","blank2":{"sentence":"___ the papers arrive on time, we will not ship the bathrobes as organic.","word":"Unless","distractors":["If","When"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Real possibility: if + present, will + verb.","tr":"Gerçek olasılık: if + geniş zaman, will + fiil.","fa":"احتمال واقعی: if + حال ساده، will + فعل.","ex":"If the towels sell well, the retailer will order more."},{"en":"No will after if.","tr":"If'ten sonra will yok.","fa":"بعد از if کلمه‌ی will نمی‌آید.","ex":"If the test goes well, not \"will go\""},{"en":"unless = if not.","tr":"unless = if not (-mezse).","fa":"unless یعنی if not.","ex":"Unless the papers arrive, we won't ship."},{"en":"No not after unless.","tr":"Unless'ten sonra not yok.","fa":"بعد از unless کلمه‌ی not نمی‌آید.","ex":"unless they arrive, not \"unless they don't arrive\""}],"test":{"en":"Look at the if-part. Is it about the future? Still use the present after if.","tr":"If kısmına bak. Gelecekle mi ilgili? Yine de if'ten sonra geniş zaman kullan.","fa":"به بخش if نگاه کن. درباره‌ی آینده است؟ باز هم بعد از if حال ساده بیاور."},"contrast":{"en":"Turkish puts the condition inside the verb (\"iyi giderse\") and Persian uses the subjunctive («اگر خوب پیش برود»); neither uses a future form here. English is the same: no will after if, even when you mean the future.","tr":"Türkçe koşulu fiilin içine koyar (\"iyi giderse\") ve burada gelecek zaman kullanmaz. İngilizce de aynıdır: anlam gelecek olsa bile if'ten sonra will gelmez, geniş zaman yeterlidir.","fa":"فارسی برای شرط از التزامی استفاده می‌کند («اگر خوب پیش برود») و اینجا زمان آینده نمی‌آورد. انگلیسی هم همین‌طور است: حتی وقتی منظورت آینده است، بعد از if کلمه‌ی will نمی‌آید و حال ساده کافی است."}},"errorWatch":[{"find":["if the test will","if they will sell","if the towels will","if sales will","unless they don't","unless the certificates don't","unless it doesn't"],"fix":{"en":"After if, use the present: \"If the test goes well, ... will ...\". After unless, no not: \"unless they arrive\".","tr":"If'ten sonra geniş zaman kullan: \"If the test goes well, ... will ...\". Unless'ten sonra not yok: \"unless they arrive\".","fa":"بعد از if حال ساده بیاور: «If the test goes well, ... will ...». بعد از unless کلمه‌ی not نیاور: «unless they arrive»."}}]},"b2":{"id":"c-mkt-12-b2","level":"B2","track":"B2","course":"marketing","unit":"mkt-12","title":"Done by a date: the future perfect (By June, we will have...)","titleTr":"Bir tarihe kadar bitmiş: future perfect (By June, we will have...)","titleFa":"تمام‌شده تا یک تاریخ: آینده‌ی کامل (By June, we will have...)","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Yapı","Örnek"],"fa":["الگو","مثال"]},"rows":[["By + time, will have + past participle","By June, the retailer will have tested the towels in twelve stores."],["By + time, won't have + past participle","By April, we won't have received the new certificates."]]},"wrong":"By June, the retailer will have test the towels in twelve stores.","right":"By June, the retailer will have tested the towels in twelve stores.","blank":{"sentence":"By September, we will have ___ 150 orders a week.","word":"reached","distractors":["reach","reaching"]},"wrong2":"Until December, we will have sent samples to five hotel groups.","right2":"By December, we will have sent samples to five hotel groups.","blank2":{"sentence":"___ December, we will have sent samples to five hotel groups.","word":"By","distractors":["Until","Since"]},"useIn":{"en":"B2: in your plan summary, use the future perfect once: By... we will have...","tr":"B2: plan özetinde future perfect'i bir kez kullan: By... we will have...","fa":"B2: در خلاصه‌ی برنامه‌ات یک بار آینده‌ی کامل بیاور: By... we will have..."},"exitItem":{"from":"mkt-12","kind":"blank","prompt":"By the end of the year, the brand will have ___ its first full year as a brand.","options":["finished","finish","finishing"],"correct":0},"expParts":{"tryFrom":"blank","rule":[{"en":"Done before a future time: will have + past participle.","tr":"Gelecekteki bir zamandan önce bitmiş: will have + üçüncü hâl.","fa":"تمام‌شده پیش از زمانی در آینده: will have + اسم مفعول.","ex":"By June, we will have tested..."},{"en":"Use by (not later than), not until.","tr":"Until değil, by (en geç) kullan.","fa":"by (حداکثر تا) بیاور، نه until.","ex":"by December, not until December"},{"en":"Negative: won't have + past participle.","tr":"Olumsuz: won't have + üçüncü hâl.","fa":"منفی: won't have + اسم مفعول.","ex":"By April, we won't have received the papers."}],"test":{"en":"Will the action be finished before the date? Then use by + will have + past participle.","tr":"Eylem o tarihten önce bitmiş olacak mı? O zaman by + will have + üçüncü hâl kullan.","fa":"کار تا آن تاریخ تمام شده خواهد بود؟ پس by + will have + اسم مفعول."},"contrast":{"en":"Turkish \"-e kadar\" and Persian «تا» cover both by and until, so learners mix them. English needs by for \"finished not later than\".","tr":"Türkçedeki \"-e kadar\" hem by hem until anlamına gelir; bu yüzden ikisi karıştırılır. İngilizcede \"en geç o zamana kadar bitmiş\" için by gerekir.","fa":"«تا» در فارسی هم معنای by را دارد هم until؛ برای همین این دو با هم اشتباه گرفته می‌شوند. انگلیسی برای «حداکثر تا آن زمان تمام‌شده» by لازم دارد."}},"errorWatch":[{"find":["will have test the","will have reach","will have send","will reached","until december, we will have","until june, we will have"],"fix":{"en":"Future perfect: by + time, will have + past participle (\"By June, we will have tested...\").","tr":"Future perfect: by + zaman, will have + üçüncü hâl (\"By June, we will have tested...\").","fa":"آینده‌ی کامل: by + زمان، will have + اسم مفعول («By June, we will have tested...»)."}}]},"vocab":{"id":"c-mkt-12-v","level":"B1","category":"vocab","course":"marketing","unit":"mkt-12","goals":["career"],"title":{"en":"Plans and Goals","tr":"Planlar ve Hedefler","fa":"برنامه و هدف"},"cards":[{"word":"content pillar","sentence":"Care tips are one content pillar for us.","meaning":{"en":"A main theme you return to again and again.","tr":"ana içerik konusu","fa":"محور محتوا"}},{"word":"milestone","sentence":"The store test is the next big milestone.","meaning":{"en":"An important point in a plan.","tr":"kilometre taşı","fa":"نقطه‌ی عطف؛ مرحله‌ی کلیدی"}},{"word":"KPI","sentence":"Repeat orders are our main KPI in the UK.","meaning":{"en":"A number that shows if you are reaching a goal (key performance indicator).","tr":"temel performans göstergesi (KPI)","fa":"شاخص کلیدی عملکرد (KPI)"}},{"word":"roll out","sentence":"The retailer may roll out the towels to more stores in the autumn.","meaning":{"en":"To make something available in more places, step by step.","tr":"yaygınlaştırmak, kademeli olarak sunmak","fa":"مرحله‌به‌مرحله گسترش دادن"}},{"word":"content calendar","sentence":"The content calendar shows every post for May.","meaning":{"en":"A plan of what you will publish, where and when.","tr":"içerik takvimi","fa":"تقویم محتوا"}},{"word":"repurpose","sentence":"We repurpose one guide as a reel and a newsletter.","meaning":{"en":"To use one piece of content again in a new form.","tr":"yeniden kullanmak","fa":"بازاستفاده کردن"}},{"word":"risk","sentence":"The biggest risk is late certificates for the bathrobes.","meaning":{"en":"Something bad that might happen.","tr":"risk","fa":"ریسک؛ خطر"}},{"word":"priority","sentence":"Germany is our first priority this spring.","meaning":{"en":"The thing that is most important and comes first.","tr":"öncelik","fa":"اولویت"}},{"word":"realistic","sentence":"Fifteen per cent is ambitious but realistic.","meaning":{"en":"Possible to reach.","tr":"gerçekçi","fa":"واقع‌بینانه"}},{"word":"on track","sentence":"We are on track for 15% if three things go right.","meaning":{"en":"Making the progress you planned.","tr":"doğru yolda, plana uygun","fa":"طبق برنامه؛ در مسیر درست"}}]},"judge":{"id":"c-mkt-12-j","course":"marketing","unit":"mkt-12","type":"judge","title":{"en":"A row you can act on","tr":"Harekete geçilebilecek bir satır","fa":"ردیفی که بشود اجرایش کرد"},"prompt":"Four lines from content calendars.","parts":["Specific","A date and an owner","Linked to a goal"],"instruction":{"en":"Tap what each line does well. A row for the calendar has all three.","tr":"Her satırın iyi yaptığı şeylere dokun. Takvime girecek satırda üçü de vardır.","fa":"روی کارهایی که هر خط درست انجام داده بزن. ردیف تقویم باید هر سه را داشته باشد."},"items":[{"by":"AI tool","answer":"Leverage omnichannel synergy to maximise brand storytelling this quarter.","present":[],"fix":{"en":"No piece, no date, no owner, and \"synergy\" is not an action. Name one piece on one channel.","tr":"Ne içerik var, ne tarih, ne sorumlu; \"synergy\" de bir eylem değil. Tek kanalda tek bir içerik söyle.","fa":"نه کاری مشخص است، نه تاریخ، نه مسئول، و «synergy» هم کار مشخصی نیست. یک کار را در یک کانال نام ببر."}},{"by":"Manager","answer":"Post more on Instagram.","present":[],"fix":{"en":"How much, what and who? \"Two care reels in May, owner: social team, goal: 200 saves.\"","tr":"Ne kadar, ne ve kim? \"Two care reels in May, owner: social team, goal: 200 saves.\"","fa":"چقدر، چه چیزی و چه کسی؟ «Two care reels in May, owner: social team, goal: 200 saves.»"}},{"by":"Good model","answer":"6 May, Instagram, reel on towel care, owner: social team, goal: 200 saves.","present":["Specific","A date and an owner","Linked to a goal"],"fix":null},{"by":"AI tool","answer":"8 May, newsletter, spring guide, owner: writer.","present":["Specific","A date and an owner"],"fix":{"en":"Clear and ready to schedule. Add why it exists: \"goal: 60 repeat orders.\"","tr":"Açık ve takvime girmeye hazır. Neden var olduğunu ekle: \"goal: 60 repeat orders.\"","fa":"روشن و آماده‌ی زمان‌بندی است. اضافه کن هدفش چیست: «goal: 60 repeat orders.»"}}]},"writing":{"id":"c-mkt-12-w","title":{"en":"A one-month content calendar","tr":"Bir aylık içerik takvimi","fa":"تقویم محتوای یک‌ماهه"},"course":"marketing","unit":"mkt-12","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":"mkt-final-7","prompt":{"en":"Plan one month (90-120 words) for your own product, or for an online towel shop: goal: repeat orders; first state three pillars; then write four rows with date, channel, piece, owner and goal; then one if line and one unless line.","tr":"Kendi ürünün ya da çevrimiçi bir havlu mağazası için bir ay planla (90-120 kelime): hedef: tekrar siparişler; önce üç ana konu söyle; sonra tarih, kanal, içerik, sorumlu ve hedefiyle dört satır yaz; sonra bir if ve bir unless satırı.","fa":"برای محصول خودت یا یک فروشگاه اینترنتی حوله یک ماه برنامه بریز (۹۰ تا ۱۲۰ کلمه): هدف: سفارش‌های تکراری؛ اول سه محور بگو؛ بعد چهار ردیف با تاریخ، کانال، کار، مسئول و هدف بنویس؛ بعد یک خط با if و یک خط با unless."},"model":"Goal: more repeat orders in May.\nPillars: care tips; how it's made; customer stories.\n6 May, Instagram, care reel, owner: social team, goal: 200 saves.\n8 May, newsletter, the same care guide, owner: writer, goal: 60 repeat orders.\n15 May, LinkedIn, factory photos, owner: social team, goal: 10 hotel messages.\n22 May, blog, customer story, owner: writer, goal: 40 clicks to the shop.\nIf the care reel gets 200 saves, we will make two more in June. Unless the customer approves her story by 15 May, we will move it to June.","frame":"Goal: ___.\nPillars: ___; ___; ___.\n___, ___, ___, owner: ___, goal: ___.\n___, ___, ___, owner: ___, goal: ___.\n___, ___, ___, owner: ___, goal: ___.\n___, ___, ___, owner: ___, goal: ___.\nIf ___, we will ___. Unless ___, we will ___.","words":[{"word":"if"},{"word":"unless"},{"word":"owner"}],"minWords":80,"minSentences":3,"rubric":["Task done: goal, three pillars, four full rows, one if, one unless","Organised: goal, pillars, rows by date, plans","Language: first conditional (if + present, will) and unless without not","Tone: realistic; one idea reused, nothing you cannot deliver"],"rubricI18n":{"tr":["Görev: hedef, üç ana konu, dört tam satır, bir if, bir unless","Düzen: hedef, ana konular, tarih sırasıyla satırlar, planlar","Dil: birinci koşul (if + geniş zaman, will) ve not olmadan unless","Üslup: gerçekçi; bir fikir yeniden kullanılıyor, yapılamayacak şey yok"],"fa":["کامل بودن کار: هدف، سه محور، چهار ردیف کامل، یک if، یک unless","نظم: هدف، محورها، ردیف‌ها به ترتیب تاریخ، برنامه‌ها","زبان: شرطی نوع اول (if + حال، will) و unless بدون not","لحن: واقع‌بینانه؛ یک ایده دوباره استفاده می‌شود و چیز غیرممکنی نیست"]}},"speaking":{"id":"mkt-12","course":"marketing","unit":"mkt-12","topic":{"en":"Presenting your content plan","tr":"İçerik planını sunmak","fa":"ارائه‌ی برنامه‌ی محتوا"},"warmup":{"en":"Think of a plan you made that went wrong. What would you plan differently now?","tr":"Ters giden bir planını düşün. Şimdi neyi farklı planlardın?","fa":"به برنامه‌ای فکر کن که خراب شد. حالا چه چیزی را جور دیگری برنامه‌ریزی می‌کنی؟"},"questions":[{"en":"Tell your manager the goal and your three pillars.","tr":"Yöneticine hedefi ve üç ana konunu söyle.","fa":"به مدیرت هدف و سه محورت را بگو."},{"en":"Say how one idea will be used on two channels, with an if.","tr":"Bir fikrin iki kanalda nasıl kullanılacağını if ile söyle.","fa":"با if بگو یک ایده چطور در دو کانال استفاده می‌شود."},{"en":"Your manager asks: \"What could stop this?\" Name one risk with unless.","tr":"Yöneticin soruyor: \"What could stop this?\" unless ile bir risk söyle.","fa":"مدیرت می‌پرسد: «What could stop this?» با unless یک ریسک نام ببر."}],"followups":[{"en":"Now present next month's plan for your own work in under a minute.","tr":"Şimdi kendi işinin gelecek ay planını bir dakikadan kısa sürede sun.","fa":"حالا برنامه‌ی ماه بعد کار خودت را در کمتر از یک دقیقه ارائه کن."}],"expressions":[{"phrase":"The goal this month is...","meaning":{"en":"Starts from the goal.","tr":"Hedefle başlar.","fa":"از هدف شروع می‌کند."}},{"phrase":"If it works, we will...","meaning":{"en":"Links a result to a decision.","tr":"Sonucu bir karara bağlar.","fa":"نتیجه را به یک تصمیم وصل می‌کند."}},{"phrase":"Unless..., we will...","meaning":{"en":"Names a risk clearly.","tr":"Riski açıkça söyler.","fa":"ریسک را روشن می‌گوید."}}],"model":"The goal this month is more repeat orders. We have three pillars: care tips, how it's made, and customer stories. On 6 May we will post one care reel, and on 8 May the newsletter will carry the same guide. If it works, we will make two more in June. Unless the customer approves her story by the 15th, we will move it.","selfCheck":[{"en":"I started from the goal.","tr":"Hedefle başladım.","fa":"از هدف شروع کردم."},{"en":"I used if + present and will correctly.","tr":"if + geniş zaman ve will'i doğru kullandım.","fa":"if + حال و will را درست به کار بردم."},{"en":"I named one risk with unless.","tr":"unless ile bir risk söyledim.","fa":"با unless یک ریسک گفتم."},{"en":"Round 3 fitted in the time.","tr":"3. tur süreye sığdı.","fa":"دور سوم را در زمان تعیین‌شده تمام کردم."}]},"exit":{"id":"c-mkt-12-x","course":"marketing","unit":"mkt-12","type":"exit","items":[{"from":"mkt-12","kind":"blank","prompt":"If the reel ___ 200 saves, we will make two more.","options":["will get","gets","got"],"correct":1,"point":2},{"from":"mkt-12","kind":"mcq","prompt":"Which calendar row can the team act on?","options":["Be more active online.","Create great content in spring.","12 June, LinkedIn, customer story, owner: writer."],"correct":2,"point":1},{"from":"mkt-12","kind":"mcq","prompt":"What are content pillars?","options":["The themes you keep coming back to","The largest posts you publish","The names of your platforms"],"correct":0,"point":1},{"from":"mkt-11","kind":"blank","prompt":"Before the shops chose us, they ___ three other suppliers.","options":["had tried","have tried","had try"],"correct":0},{"from":"mkt-9","kind":"blank","prompt":"The company apologised ___ the late reply.","options":["to","of","for"],"correct":2},{"from":"mkt-2","kind":"mcq","prompt":"Where do you find your reader's real words?","options":["Reviews and customer emails","A list of nice adjectives","A competitor's logo"],"correct":0}]},"explain":{"id":"c-mkt-12-e","course":"marketing","unit":"mkt-12","type":"explain","level":"B1","title":{"en":"The content calendar","tr":"İçerik takvimi","fa":"تقویم محتوا"},"objective":{"en":"In this lesson you will learn to plan a content calendar with pillars, dates and owners.","tr":"Bu derste ana konuları, tarihleri ve sorumluları belli bir içerik takvimi planlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری یک تقویم محتوا با محورها، تاریخ‌ها و مسئول هر کار بچینی."},"hook":{"en":"Good content is rarely a lucky idea. It comes from a simple plan your team can follow.","tr":"İyi içerik nadiren şanslı bir fikirdir. Ekibinin izleyebileceği basit bir plandan doğar.","fa":"محتوای خوب به‌ندرت یک ایده‌ی شانسی است. حاصل برنامه‌ای ساده است که تیمت بتواند دنبالش کند."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The craft","tr":"Beceri","fa":"مهارت"},"head":{"en":"Build the calendar","tr":"Takvimi kur","fa":"تقویم را بساز"},"steps":[{"en":"Start from the goal and the reader, not from today's idea.","tr":"Bugünün fikrinden değil, hedeften ve okurdan başla.","fa":"از هدف و مخاطب شروع کن، نه از ایده‌ی امروز.","ex":"Goal: repeat orders from people who bought once."},{"en":"Choose three or four pillars: the themes you return to.","tr":"Üç ya da dört ana konu seç: sürekli döneceğin temalar.","fa":"سه یا چهار محور انتخاب کن: موضوع‌هایی که مدام به آن‌ها برمی‌گردی.","ex":"Care tips. How it's made. Customer stories."},{"en":"Plan one core idea a week, and reuse it across channels.","tr":"Haftada bir ana fikir planla ve onu kanallarda yeniden kullan.","fa":"برای هر هفته یک ایده‌ی اصلی در نظر بگیر و در کانال‌های مختلف دوباره از آن استفاده کن.","ex":"One guide becomes a reel, a post and a newsletter."},{"en":"Give each row a date, channel, format, owner and goal.","tr":"Her satıra tarih, kanal, biçim, sorumlu ve hedef ver.","fa":"به هر ردیف تاریخ، کانال، قالب، مسئول و هدف بده.","ex":"6 May, Instagram, reel, social team, 200 saves."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Plans with conditions: if + present, will; unless","tr":"Koşullu planlar: if + geniş zaman, will; unless","fa":"برنامه با شرط: if + حال ساده، will؛ unless"},"steps":[{"en":"Real possibility: if + present, will + verb.","tr":"Gerçek olasılık: if + geniş zaman, will + fiil.","fa":"احتمال واقعی: if + حال ساده، will + فعل.","ex":"If the towels sell well, the retailer will order more."},{"en":"No will after if.","tr":"If'ten sonra will yok.","fa":"بعد از if کلمه‌ی will نمی‌آید.","ex":"If the test goes well, not \"will go\""},{"en":"unless = if not.","tr":"unless = if not (-mezse).","fa":"unless یعنی if not.","ex":"Unless the papers arrive, we won't ship."},{"en":"No not after unless.","tr":"Unless'ten sonra not yok.","fa":"بعد از unless کلمه‌ی not نمی‌آید.","ex":"unless they arrive, not \"unless they don't arrive\""}],"table":{"headers":{"en":["Condition","Result"],"tr":["Koşul","Sonuç"],"fa":["شرط","نتیجه"]},"rows":[["If the towels sell well,","the retailer will order for more stores."],["If repeat orders keep growing,","we will reach 150 orders a week."],["Unless the certificates arrive on time,","the bathrobes will be late."]]},"tip":{"en":"Turkish puts the condition inside the verb (\"iyi giderse\") and Persian uses the subjunctive («اگر خوب پیش برود»); neither uses a future form here. English is the same: no will after if, even when you mean the future.","tr":"Türkçe koşulu fiilin içine koyar (\"iyi giderse\") ve burada gelecek zaman kullanmaz. İngilizce de aynıdır: anlam gelecek olsa bile if'ten sonra will gelmez, geniş zaman yeterlidir.","fa":"فارسی برای شرط از التزامی استفاده می‌کند («اگر خوب پیش برود») و اینجا زمان آینده نمی‌آورد. انگلیسی هم همین‌طور است: حتی وقتی منظورت آینده است، بعد از if کلمه‌ی will نمی‌آید و حال ساده کافی است."}},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Keeping the calendar alive","tr":"Takvimi canlı tutmak","fa":"زنده نگه داشتن تقویم"},"body":{"en":"Keep a status column: idea, draft, approved, live. Add a results column, and look at it once a month. Leave some empty slots for news, because plans change.","tr":"Bir durum sütunu tut: fikir, taslak, onaylı, yayında. Bir de sonuç sütunu ekle ve ayda bir bak. Haberler için birkaç boş yer bırak, çünkü planlar değişir.","fa":"یک ستون وضعیت داشته باش: ایده، پیش‌نویس، تأییدشده، منتشرشده. یک ستون نتیجه هم اضافه کن و ماهی یک بار آن را مرور کن. چند جای خالی برای خبرها بگذار، چون برنامه‌ها عوض می‌شوند."},"phrases":[{"phrase":"The goal this month is...","meaning":{"en":"Starts from the goal.","tr":"Hedefle başlar.","fa":"از هدف شروع می‌کند."}},{"phrase":"If it works, we will...","meaning":{"en":"Links a result to a decision.","tr":"Sonucu bir karara bağlar.","fa":"نتیجه را به یک تصمیم وصل می‌کند."}},{"phrase":"Unless..., we will...","meaning":{"en":"Names a risk clearly.","tr":"Riski açıkça söyler.","fa":"ریسک را روشن می‌گوید."}},{"phrase":"content pillar","meaning":{"en":"A main theme you return to again and again.","tr":"ana içerik konusu","fa":"محور محتوا"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a wish into a calendar row","tr":"Bir dileği takvim satırına çevir","fa":"یک آرزو را به ردیف تقویم تبدیل کن"},"item":"Post more on social media and go viral this summer.","answer":"6 May, Instagram, one reel on towel care, owner: social team. If it gets 200 saves, we will make two more.","walk":[{"en":"Ask what, where and when: one piece, one channel, one date.","tr":"Ne, nerede, ne zaman diye sor: tek parça, tek kanal, tek tarih.","fa":"بپرس چه، کجا، کی: یک کار، یک کانال، یک تاریخ."},{"en":"Name one owner, so that someone is responsible.","tr":"Tek bir sorumlu söyle ki iş birinin üzerinde olsun.","fa":"یک مسئول نام ببر تا کار گردن کسی باشد."},{"en":"Add a number you can check, and what you will do if you reach it.","tr":"Kontrol edebileceğin bir rakam ve ona ulaşırsan ne yapacağını ekle.","fa":"عددی که بشود بررسی کرد و کاری را که اگر به آن رسیدی انجام می‌دهی اضافه کن."}]},"quick":{"prompt":"Pillars are the ___ you come back to again and again.","options":["themes","platforms","deadlines"],"correct":0,"why":{"en":"themes: pillars keep your content varied but still clearly about the same few things.","tr":"themes: ana konular içeriğini çeşitli ama yine de aynı birkaç şeye odaklı tutar.","fa":"themes: محورها محتوایت را متنوع نگه می‌دارند، ولی همچنان درباره‌ی همان چند موضوع."}},"remember":{"en":"Every row needs a date, an owner and a reason to exist.","tr":"Her satırın bir tarihi, bir sorumlusu ve var olma nedeni olmalı.","fa":"هر ردیف باید تاریخ، مسئول و دلیلی برای بودن داشته باشد."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Done by a date: the future perfect (By June, we will have...)","tr":"Bir tarihe kadar bitmiş: future perfect (By June, we will have...)","fa":"تمام‌شده تا یک تاریخ: آینده‌ی کامل (By June, we will have...)"},"steps":[{"en":"Done before a future time: will have + past participle.","tr":"Gelecekteki bir zamandan önce bitmiş: will have + üçüncü hâl.","fa":"تمام‌شده پیش از زمانی در آینده: will have + اسم مفعول.","ex":"By June, we will have tested..."},{"en":"Use by (not later than), not until.","tr":"Until değil, by (en geç) kullan.","fa":"by (حداکثر تا) بیاور، نه until.","ex":"by December, not until December"},{"en":"Negative: won't have + past participle.","tr":"Olumsuz: won't have + üçüncü hâl.","fa":"منفی: won't have + اسم مفعول.","ex":"By April, we won't have received the papers."}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Yapı","Örnek"],"fa":["الگو","مثال"]},"rows":[["By + time, will have + past participle","By June, the retailer will have tested the towels in twelve stores."],["By + time, won't have + past participle","By April, we won't have received the new certificates."]]},"body":{"en":"B2: in your plan summary, use the future perfect once: By... we will have...","tr":"B2: plan özetinde future perfect'i bir kez kullan: By... we will have...","fa":"B2: در خلاصه‌ی برنامه‌ات یک بار آینده‌ی کامل بیاور: By... we will have..."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
